    const nonSelectObj = (document.formCheck || { elements: [] }).nonSelect;
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if (nonSelectObj.checked === true) {
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
        nonSelectObj.checked = false;
    }
    if (scwin.chkArrNo.length !== 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    scwin.rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkArrNo.join("\n");
    docs.innerHTML = scwin.chkTitle.join("<br/>");
};

/**
 * @method
 * @name resetRtnVal
 * @description reset Rtn Val 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.resetRtnVal = function (ver) {
    const tmpArr1 = [];
    const tmpArr2 = [];
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = [];
    scwin.chkTitle = [];
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
};

