/**
 * @method
 * @name replaceAll
 * @description replace All 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.replaceAll = function (ver) {
    while (ver.indexOf('<br/>') > -1) {
        ver = ver.replace('<br/>', '\r\n');
    }
    while (ver.indexOf('#039;') > -1) {
        ver = ver.replace('#039;', '\'');
    }
    while (ver.indexOf('quot;') > -1) {
        ver = ver.replace('quot;', '\"');
    }
    return ver;
};

